-- Hand-written: rt1 T2: a debit note on an export under LUT is issued only with a LUT saved for the financial year of its own issue day, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `documents_debit_note_lut_fy` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type = 'debit_note' AND (NEW.export_mode IS 'lut' OR NEW.supply_type IS 'export_lut' OR EXISTS (SELECT 1 FROM documents p WHERE p.id = NEW.parent_id AND (p.export_mode IS 'lut' OR p.supply_type IS 'export_lut'))) AND (NEW.issue_date IS NULL OR NOT EXISTS (SELECT 1 FROM settings ts WHERE ts.key = 'tax' AND (
           EXISTS (SELECT 1 FROM json_each(ts.value, '$.luts') l WHERE json_extract(l.value, '$.fy') = (CASE WHEN CAST(substr(NEW.issue_date, 6, 2) AS INTEGER) >= 4 THEN substr(NEW.issue_date, 3, 2) || printf('%02d', (CAST(substr(NEW.issue_date, 3, 2) AS INTEGER) + 1) % 100) ELSE printf('%02d', (CAST(substr(NEW.issue_date, 3, 2) AS INTEGER) + 99) % 100) || substr(NEW.issue_date, 3, 2) END) AND trim(coalesce(json_extract(l.value, '$.arn'), '')) <> '')
           OR (json_extract(ts.value, '$.lut.fy') = (CASE WHEN CAST(substr(NEW.issue_date, 6, 2) AS INTEGER) >= 4 THEN substr(NEW.issue_date, 3, 2) || printf('%02d', (CAST(substr(NEW.issue_date, 3, 2) AS INTEGER) + 1) % 100) ELSE printf('%02d', (CAST(substr(NEW.issue_date, 3, 2) AS INTEGER) + 99) % 100) || substr(NEW.issue_date, 3, 2) END) AND trim(coalesce(json_extract(ts.value, '$.lut.arn'), '')) <> '')))) BEGIN SELECT RAISE(ABORT, 'documents_debit_note_lut_fy: a debit note on an export under LUT needs a LUT saved for the financial year of its own issue day'); END;
